Table Columns Records <code>customers</code> id, name, email, city, joined_date 8 <code>products</code> id, name, category, price, stock, description 15 <code>orders</code> id, customer_id, order_date, total_amount, status 8 <code>order_items</code> id, order_id, product_id, quantity, unit_price 12 <pre><code>SELECT name, category, price FROM products ORDER BY price DESC LIMIT 5;

SELECT category, COUNT(*) as count, AVG(price) as avg_price
FROM products GROUP BY category ORDER BY count DESC;

SELECT o.id, c.name, o.order_date, o.total_amount, o.status
FROM orders o JOIN customers c ON o.customer_id = c.id
ORDER BY o.order_date DESC;

SELECT status, COUNT(*) as order_count, SUM(total_amount) as total_revenue
FROM orders GROUP BY status;

SELECT DISTINCT c.name, c.city, COUNT(o.id) as order_count
FROM customers c JOIN orders o ON c.id = o.customer_id
GROUP BY c.id ORDER BY order_count DESC;
</code></pre> <p>Orders #3 and #7 intentionally have <code>total_amount</code> values that differ from their <code>order_items</code> totals. You should report that discrepancy.</p>
